    Conflict,
    Database(sqlx::Error),
    Event(EventServiceError),
    InvalidInput,
    NotFound,
}

impl From<sqlx::Error> for SharedViewError {
    fn from(error: sqlx::Error) -> Self {
        Self::Database(error)
    }
}

